/** Explicit local I/O benchmark. Generated bytes are not scientific data.
 * No model method is called; this isolates Core provenance/checking overhead.
 */
import assert from 'node:assert/strict';
import { createHash, randomFillSync } from 'node:crypto';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { mkdir, open, readFile, stat, statfs, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { performance } from 'node:perf_hooks';
import { fileURLToPath } from 'node:url';
import { createAgent, createRunStore, checkRun } from '../packages/core/dist/index.js';
import { checkRunUnlocked } from '../packages/core/dist/runs/check.js';
import { acquireOperation } from '../packages/core/dist/store/lock.js';
import { hashArtifacts } from '../packages/core/dist/runs/provenance.js';

const exec = promisify(execFile);
const repository = fileURLToPath(new URL('..', import.meta.url));
const args = process.argv.slice(2);
const value = (name, fallback) => { const index = args.indexOf(name); return index < 0 ? fallback : args[index + 1]; };
if (!args.includes('--run')) {
  console.log('Opt-in only: node scripts/benchmark-large.mjs --run [--sizes-mib 512,1024] [--output DIRECTORY] [--python python3]');
  console.log('Writes and retains real non-sparse generated files. No model inference. Default input allocation: 1.5 GiB.');
  process.exit(0);
}
const sizes = value('--sizes-mib', '512,1024').split(',').map(Number);
if (!sizes.length || sizes.some(size => !Number.isSafeInteger(size) || size < 1 || size > 8192)) throw new Error('--sizes-mib requires comma-separated integers from 1 to 8192.');
const destination = path.resolve(value('--output', path.join(repository, '.artifacts/large-file-benchmark', new Date().toISOString().replace(/[:.]/g, '-'))));
const python = value('--python', 'python3');
await mkdir(destination, { recursive: true });
const filesystem = await statfs(destination);
const availableBytes = filesystem.bavail * filesystem.bsize;
const requiredBytes = sizes.reduce((sum, mib) => sum + mib * 1024 ** 2, 0);
if (availableBytes < requiredBytes + 512 * 1024 ** 2) throw new Error(`Insufficient free space: need ${requiredBytes} input bytes plus 512 MiB headroom.`);

const readIo = async () => {
  try { return Object.fromEntries((await readFile('/proc/self/io', 'utf8')).trim().split('\n').map(line => { const [name, bytes] = line.split(':'); return [name, Number(bytes.trim())]; })); }
  catch { return null; }
};
const difference = (before, after) => before && after ? Object.fromEntries(Object.keys(after).map(key => [key, after[key] - before[key]])) : null;
async function measure(action) {
  const before = await readIo();
  const started = performance.now();
  const result = await action();
  const milliseconds = performance.now() - started;
  const after = await readIo();
  return { result, milliseconds, processIoDelta: difference(before, after), rssBytesAtEnd: process.memoryUsage().rss };
}
async function writeFull(file, bytes) {
  const handle = await open(file, 'wx');
  const buffer = Buffer.alloc(1024 ** 2);
  const digest = createHash('sha256');
  let written = 0;
  try {
    while (written < bytes) {
      const length = Math.min(buffer.length, bytes - written);
      randomFillSync(buffer, 0, length); // fresh bytes: no sparse seek, reused zero block or compression shortcut
      digest.update(buffer.subarray(0, length));
      let offset = 0;
      while (offset < length) {
        const part = await handle.write(buffer, offset, length - offset, written + offset);
        if (!part.bytesWritten) throw new Error('Input write made no progress.');
        offset += part.bytesWritten;
      }
      written += length;
    }
    await handle.sync();
  } finally { await handle.close(); }
  const info = await stat(file);
  assert.equal(info.size, bytes);
  assert.ok(info.blocks * 512 >= bytes, 'file allocation must cover logical bytes; sparse files are rejected');
  return { sha256: digest.digest('hex'), writtenBytes: written, logicalBytes: info.size, allocatedBytes: info.blocks * 512, filesystemBlockSize: info.blksize };
}

const checker = String.raw`import hashlib,json,os,time
from pathlib import Path
root=Path(os.environ['AGENT_ROOT'])
output=Path(os.environ['AGENT_OUTPUT_DIR'])
def io():
    try:return {k:int(v) for k,v in (line.split(':',1) for line in Path('/proc/self/io').read_text().splitlines())}
    except OSError:return None
before=io();start=time.perf_counter();digest=hashlib.sha256();count=0
with (root/'data/input.bin').open('rb') as source:
    while True:
        chunk=source.read(1024*1024)
        if not chunk:break
        digest.update(chunk);count+=len(chunk)
seconds=time.perf_counter()-start;after=io()
claimed=json.loads((output/'digest.json').read_text())
passed=count==claimed['bytes'] and digest.hexdigest()==claimed['sha256']
report={'status':'passed' if passed else 'failed','checks':[{'name':'independent streaming input SHA256 and byte count','status':'passed' if passed else 'failed'}],'issues':[] if passed else ['Source digest/bytes disagree with claimed artifact']}
Path(os.environ['AGENT_CHECK_FILE']).write_text(json.dumps(report)+'\n')
print('BENCHMARK_COUNTERS '+json.dumps({'inputBytesRead':count,'inputReadSeconds':seconds,'processIoDelta':{k:after[k]-before[k] for k in after} if before and after else None}))
raise SystemExit(0 if passed else 1)
`;

let modelCalls = 0;
const noInferenceModel = { specificationVersion: 'v4', provider: 'local-benchmark', modelId: 'no-inference', supportedUrls: {},
  async doGenerate() { modelCalls++; throw new Error('Benchmark must not invoke a model.'); },
  async doStream() { modelCalls++; throw new Error('Benchmark must not invoke a model.'); },
};
const manifest = JSON.parse(await readFile(path.join(repository, 'packages/core/package.json'), 'utf8'));
const ai = JSON.parse(await readFile(path.join(repository, 'node_modules/ai/package.json'), 'utf8'));
const pythonVersion = (await exec(python, ['--version'])).stdout.trim();
const report = { kind: 'generated-nonsparse-local-io-benchmark', status: 'running', startedAt: new Date().toISOString(), destination,
  versions: { core: manifest.version, aiSdk: ai.version, node: process.version, python: pythonVersion },
  platform: { os: os.type(), release: os.release(), architecture: os.arch(), cpu: os.cpus()[0]?.model, totalMemoryBytes: os.totalmem(), filesystemType: filesystem.type, filesystemBlockSize: filesystem.bsize, initialAvailableBytes: availableBytes },
  methodology: { modelInference: false, generatedScientificData: false, generation: 'Fresh cryptographic random bytes, full sequential writes, file fsync; stat allocated blocks >= logical size.', cache: 'Files are generated immediately before hashing. No OS cache drop. Results include warm-cache and shared/NFS effects; not cold-disk throughput.', bytesRead: 'Provenance baseline byte count and Python checker loop byte counts are exact. Linux /proc/self/io deltas are observed process counters and include metadata/other reads; read_bytes is not a reliable NFS/cache-miss throughput measure.', lifecycle: 'Direct createRunStore + initial checkRunUnlocked under project lock + public checkRun isolate provenance/checker overhead; no model execution latency is included.', inputsRetained: true }, results: [] };
const saveReport = () => writeFile(path.join(destination, 'results.json'), JSON.stringify(report, null, 2) + '\n');
await saveReport();
try {
  for (const mib of sizes) {
    const root = path.join(destination, `${mib}MiB`);
    await mkdir(path.join(root, 'data'), { recursive: true });
    await mkdir(path.join(root, 'tools'), { recursive: true });
    await writeFile(path.join(root, 'tools/check-input.py'), checker);
    const generated = await measure(() => writeFull(path.join(root, 'data/input.bin'), mib * 1024 ** 2));
    const config = { root, model: noInferenceModel, instructions: { text: 'Generated I/O benchmark. No inference or scientific analysis.' }, provenance: { inputs: ['data/input.bin'] }, validation: { command: [python, 'tools/check-input.py'], timeoutMs: 120_000 } };
    const startup = await measure(() => createAgent(config));
    const agent = startup.result;
    try {
      const store = createRunStore(config);
      const release = await acquireOperation(root);
      let creation, initial;
      try {
        creation = await measure(() => store.create('Generated byte I/O benchmark; no model call.', 'benchmark-session', { inputs: ['data/input.bin'] }));
        const run = creation.result;
        await writeFile(path.join(run.directory, 'output/digest.json'), JSON.stringify({ bytes: generated.result.writtenBytes, sha256: generated.result.sha256 }) + '\n');
        run.execution = 'completed'; run.finishedAt = new Date().toISOString(); run.artifacts = ['output/digest.json'];
        run.provenance.artifacts = await hashArtifacts(root, run.id, run.artifacts);
        await store.save(run);
        initial = await measure(() => checkRunUnlocked(config, run.id, undefined, { initial: true }));
      } finally { await release(); }
      assert.equal(initial.result.delivery, 'passed');
      const initialLog = await readFile(path.join(initial.result.directory, 'validation.log'), 'utf8');
      const rechecked = await measure(() => checkRun(config, initial.result.id));
      assert.equal(rechecked.result.delivery, 'passed');
      const recheckLog = await readFile(path.join(rechecked.result.directory, 'validation.log'), 'utf8');
      const counters = log => JSON.parse(log.match(/BENCHMARK_COUNTERS (.+)/u)[1]);
      const phase = measurement => ({ milliseconds: measurement.milliseconds, processIoDelta: measurement.processIoDelta, rssBytesAtEnd: measurement.rssBytesAtEnd });
      report.results.push({ mib, input: generated.result, phases: { generation: phase(generated), createAgentStartup: phase(startup), runCreationAndProvenance: { ...phase(creation), inputBytesHashed: creation.result.provenance.inputs.reduce((sum, file) => sum + file.bytes, 0) }, initialCheck: { ...phase(initial), checker: counters(initialLog) }, recheck: { ...phase(rechecked), checker: counters(recheckLog) } }, execution: rechecked.result.execution, initialDelivery: initial.result.delivery, recheckDelivery: rechecked.result.delivery, runId: rechecked.result.id, runDirectory: rechecked.result.directory });
      await saveReport();
      console.log(JSON.stringify({ mib, allocatedBytes: generated.result.allocatedBytes, startupMs: startup.milliseconds, provenanceMs: creation.milliseconds, initialCheckMs: initial.milliseconds, recheckMs: rechecked.milliseconds }));
    } finally { await agent.close(); }
  }
  assert.equal(modelCalls, 0);
  report.status = 'passed'; report.modelCalls = modelCalls;
} catch (error) { report.status = 'failed'; report.error = error.message; throw error; }
finally { report.finishedAt = new Date().toISOString(); await saveReport(); }
console.log(JSON.stringify({ status: report.status, scenarios: report.results.length, modelCalls, report: path.join(destination, 'results.json') }));
